using System;using System.Linq;using System.Collections.Generic;using System.Windows;using System.Windows.Controls;using System.Windows.Media;
namespace gazegallery;
public static class BindingMap34 {
 public static string Normalize(string key)=>key.Replace("Return","Enter",StringComparison.OrdinalIgnoreCase).Replace("Control+","Ctrl+",StringComparison.OrdinalIgnoreCase).Replace("D0","0").Replace("D1","1").Replace("D2","2").Replace("D3","3").Replace("D4","4").Replace("D5","5").Replace("D6","6").Replace("D7","7").Replace("D8","8").Replace("D9","9");
 public static string[] Actions(string mode,string key,Dictionary<string,string[]> bindings){bool Allowed(string action)=>mode switch{"Thumbnails"=>!action.StartsWith("Plugin:",StringComparison.OrdinalIgnoreCase)&&!action.EndsWith("collage",StringComparison.OrdinalIgnoreCase)&&action is not ("Next" or "Previous" or "Crop" or "Play / pause" or "Mute" or "Slideshow" or "Filmstrip" or "Grayscale view" or "Slideshow toggle"),"Collage"=>action.EndsWith("collage",StringComparison.OrdinalIgnoreCase)||action is "Fullscreen" or "Exit" or "Undo" or "Paste" or "Crop" or "Copy",_=>!action.EndsWith("collage",StringComparison.OrdinalIgnoreCase)&&!action.EndsWith("thumbnails",StringComparison.OrdinalIgnoreCase)};var actions=bindings.Where(k=>Allowed(k.Key)&&k.Value.Any(v=>Normalize(v).Equals(Normalize(key),StringComparison.OrdinalIgnoreCase))).Select(k=>k.Key).ToList();void Add(string binding,string action){if(key.Equals(binding,StringComparison.OrdinalIgnoreCase)&&!actions.Contains(action))actions.Add(action);}if(mode=="Thumbnails"){Add("W","View selected image");Add("Ctrl+A","Select / deselect all");Add("Alt","Hover for peek preview");Add("Ctrl+WheelUp","Larger thumbnails");Add("Ctrl+WheelDown","Smaller thumbnails");}if(mode=="Collage"){Add("Ctrl+A","Select / deselect all");Add("B","Remove selected");Add("C","Crop single selection");Add("Ctrl+V","Paste");Add("Enter","Fullscreen");}if(mode=="Viewer"){Add("WheelUp","Zoom in (video: volume)");Add("WheelDown","Zoom out (video: volume)");Add("Ctrl+WheelUp","Video zoom in / borderless resize");Add("Ctrl+WheelDown","Video zoom out / borderless resize");}return actions.Distinct().ToArray();}
}
public partial class MainWindow {
 void ShowBindingGuide34(Window owner,Func<Dictionary<string,string[]>> getBindings){var w=Ui.Dialog(owner,"Keyboard and mouse guide",900,570);var panel=new DockPanel{Margin=new Thickness(14)};var top=new StackPanel{Orientation=Orientation.Horizontal};var modes=new ComboBox{Width=130,ItemsSource=new[]{"Viewer","Thumbnails","Collage"},SelectedIndex=0,Margin=new(0,0,12,6)};top.Children.Add(modes);var modifiers=new List<CheckBox>();foreach(string name in new[]{"Ctrl","Shift","Alt"}){var c=new CheckBox{Content=name,Foreground=Ui.Fg,Margin=new(8,0,8,6)};modifiers.Add(c);top.Children.Add(c);}DockPanel.SetDock(top,Dock.Top);panel.Children.Add(top);var detail=Ui.Label("Click a key or mouse control to see its actions. Rebind in the existing editor.",12);detail.TextWrapping=TextWrapping.Wrap;detail.MinHeight=48;DockPanel.SetDock(detail,Dock.Bottom);panel.Children.Add(detail);var diagram=new StackPanel();panel.Children.Add(diagram);void Render(){diagram.Children.Clear();var bindings=getBindings();string mode=(string)modes.SelectedItem;string layer=string.Join("+",modifiers.Where(c=>c.IsChecked==true).Select(c=>c.Content));if(layer.Length>0)layer+="+";foreach(string row in new[]{"Escape F1 F2 F3 F4 F5 F6 F7 F8 F9 F10 F11 F12","OemTilde D1 D2 D3 D4 D5 D6 D7 D8 D9 D0 OemMinus OemPlus Back","Tab Q W E R T Y U I O P OemOpenBrackets OemCloseBrackets","Capital A S D F G H J K L OemSemicolon OemQuotes Enter","LeftShift Z X C V B N M OemComma OemPeriod OemQuestion RightShift","LeftCtrl LeftAlt Space RightAlt RightCtrl Left Up Down Right","Insert Delete Home End PageUp PageDown","NumPad7 NumPad8 NumPad9 Divide NumPad4 NumPad5 NumPad6 Multiply NumPad1 NumPad2 NumPad3 Subtract NumPad0 Decimal Add"}){var line=new WrapPanel{HorizontalAlignment=HorizontalAlignment.Center,Margin=new(0,2,0,2)};foreach(string key in row.Split(' ')){string chord=layer+key;var assigned=BindingMap34.Actions(mode,chord,bindings);var button=Ui.Button(KeyCaption34(key),()=>detail.Text=FriendlyKey(chord)+": "+(assigned.Length==0?"No binding in this mode":string.Join(" · ",assigned)));button.Width=key=="Space"?180:key.Contains("Shift")||key=="Back"?72:48;button.Height=30;button.FontSize=10;if(assigned.Length>0)button.BorderBrush=new SolidColorBrush(Color.FromRgb(78,76,50));button.BorderThickness=new(assigned.Length>0?1:0);TintBinding37(button,assigned.Length>0);line.Children.Add(button);}diagram.Children.Add(line);}diagram.Children.Add(Ui.Label("Mouse — mode and modifier sensitive",12));var mouse=new WrapPanel{HorizontalAlignment=HorizontalAlignment.Center};foreach(string key in new[]{"LeftClick","RightClick","MouseMiddle","MouseBack","MouseForward","WheelUp","WheelDown"}){string chord=layer+key;var a=BindingMap34.Actions(mode,chord,bindings);var button=Ui.Button(key,()=>detail.Text=chord+": "+(a.Length>0?string.Join(" · ",a):key=="RightClick"?"Context menu":key=="LeftClick"?"Select / pan / drag, depending on mode":"No configured binding"));TintBinding37(button,a.Length>0||key is "LeftClick" or "RightClick");mouse.Children.Add(button);}diagram.Children.Add(mouse);}foreach(var c in modifiers){c.Checked+=(_,_)=>Render();c.Unchecked+=(_,_)=>Render();}modes.SelectionChanged+=(_,_)=>Render();Render();w.Content=new ScrollViewer{Content=panel,HorizontalScrollBarVisibility=ScrollBarVisibility.Disabled};w.ShowDialog();}
 static string KeyCaption34(string key)=>key switch{"Escape"=>"Esc","Capital"=>"Caps","OemTilde"=>"~","OemMinus"=>"−","OemPlus"=>"+","OemOpenBrackets"=>"[","OemCloseBrackets"=>"]","OemSemicolon"=>";","OemQuotes"=>"'","OemComma"=>",","OemPeriod"=>".","OemQuestion"=>"/",_=>BindingMap34.Normalize(key).Replace("LeftShift","Shift").Replace("RightShift","Shift").Replace("LeftCtrl","Ctrl").Replace("RightCtrl","Ctrl").Replace("LeftAlt","Alt").Replace("RightAlt","Alt").Replace("NumPad","N")};
}
